<script setup lang="ts">
import {PhPackage,PhArrowRight} from '@phosphor-icons/vue'
import type { WorkspaceNavigation } from '../types/workspace'
import type { Finding } from '../types/findings'
import {materialRequestStatuses,type MaterialDialogTarget} from '../types/materialRequests'
import {inventoryWithRequests,workOrderCode,materialQuantities,materialEditingAllowed} from '../utils/materialRequests'
import {availableStock,formatDate} from '../data/operations'
const props=defineProps<{findings:Finding[];storageReady:boolean;storageError:string;navigation?:WorkspaceNavigation|null}>()
defineEmits<{action:[target:MaterialDialogTarget];openWork:[id:string]}>()
const filter=ref('active'),findingId=ref('')
watch(()=>props.navigation?.id,()=>{if(!props.navigation){filter.value='active';findingId.value=''}else if(props.navigation.tab==='inventory'){filter.value=props.navigation.requests??'active';findingId.value=props.navigation.findingId??''}},{immediate:true})
const parts=computed(()=>inventoryWithRequests(props.findings))
const rows=computed(()=>props.findings.flatMap(finding=>(finding.materialRequests??[]).map(request=>({finding,request,part:parts.value.find(p=>p.id===request.partId)!}))).sort((a,b)=>b.request.createdAt.localeCompare(a.request.createdAt)))
const filtered=computed(()=>rows.value.filter(row=>(!findingId.value||row.finding.id===findingId.value)&&(filter.value==='all'||(filter.value==='pending'?(['requested','ready'].includes(row.request.status)||materialQuantities(row.request).remaining>0):filter.value==='active'?(materialEditingAllowed(row.finding)&&(['requested','ready'].includes(row.request.status)||materialQuantities(row.request).remaining>0)):filter.value==='unsettled'?materialQuantities(row.request).remaining>0:row.request.status===filter.value))))
</script>
<template>
 <section class="material-queue" aria-labelledby="material-queue-title">
  <div class="operations-section-heading"><div><h3 id="material-queue-title">Permintaan dari pekerjaan</h3><p>Diajukan belum mengurangi stok. Siapkan untuk alokasi, lalu catat penyerahan, pemakaian, dan pengembalian.</p></div><label class="operations-select"><span>Status permintaan</span><select v-model="filter" aria-label="Filter permintaan sparepart"><option value="active">Aktif</option><option value="pending">Perlu tindak lanjut</option><option value="all">Semua permintaan</option><option value="unsettled">Belum dicatat pemakaiannya</option><option v-for="(label,key) in materialRequestStatuses" :key="key" :value="key">{{ label }}</option></select></label></div>
  <p v-if="findingId" class="queue-work-filter">Permintaan untuk {{ findings.find(f=>f.id===findingId)?.title??'pekerjaan terpilih' }}<button class="text-button" @click="findingId=''">Tampilkan semua pekerjaan</button></p>
  <p v-if="!storageReady||storageError" class="material-empty" role="status">{{ storageError||'Membuka permintaan lokal…' }}</p>
  <p v-else-if="!filtered.length" class="material-empty"><PhPackage :size="21" />{{ rows.length?'Tidak ada permintaan pada filter ini.':'Belum ada permintaan. Buka pekerjaan lalu pilih Request sparepart.' }}</p>
  <div v-else class="material-request-list"><article v-for="{finding,request,part} in filtered" :key="request.id" class="material-request-card" :data-request-id="request.id" :data-request-status="request.status"><div class="material-request-meta"><span class="record-code">{{ workOrderCode(finding) }}</span><span class="material-status" :class="request.status">{{ materialRequestStatuses[request.status] }}</span></div><h4>{{ part.name }} <span>{{ request.quantity }} {{ part.unit }}</span></h4><p>{{ finding.title }}</p><small>{{ part.partNumber }} · {{ part.location }} · {{ formatDate(request.createdAt) }}</small><p class="material-purpose">{{ request.note }}</p><p v-if="request.status==='requested'" class="field-help">Tersedia {{ availableStock(part) }} {{ part.unit }}<span v-if="availableStock(part)<request.quantity"> · Stok belum cukup untuk disiapkan.</span></p><div v-if="request.status==='issued'" class="material-disposition-details"><p>Dipakai {{ materialQuantities(request).used }} · Dikembalikan {{ materialQuantities(request).returned }} · Belum dicatat {{ materialQuantities(request).remaining }} {{ part.unit }}</p><small v-for="entry in request.dispositions??[]" :key="entry.id">{{ entry.kind==='used'?'Dipakai':'Dikembalikan' }} {{ entry.quantity }} · {{ entry.actor }}<template v-if="entry.serialLot"> · Seri/lot {{ entry.serialLot }}</template> · {{ entry.note }}</small></div><div class="material-request-actions"><template v-if="request.status==='issued'&&materialQuantities(request).remaining>0"><button class="button primary use-material" :disabled="!materialEditingAllowed(finding)" @click="$emit('action',{findingId:finding.id,requestId:request.id,disposition:'used'})">Catat dipakai</button><button class="button subtle return-material" :disabled="!materialEditingAllowed(finding)" @click="$emit('action',{findingId:finding.id,requestId:request.id,disposition:'returned'})">Kembalikan sisa</button></template><button v-if="request.status==='requested'" class="button primary prepare-material" :disabled="availableStock(part)<request.quantity||!materialEditingAllowed(finding)" @click="$emit('action',{findingId:finding.id,requestId:request.id,status:'ready'})">Siapkan part</button><button v-if="request.status==='ready'" class="button primary issue-material" :disabled="!materialEditingAllowed(finding)" @click="$emit('action',{findingId:finding.id,requestId:request.id,status:'issued'})">Serahkan part</button><button v-if="['requested','ready'].includes(request.status)" class="button subtle cancel-material" :disabled="!materialEditingAllowed(finding)" @click="$emit('action',{findingId:finding.id,requestId:request.id,status:'cancelled'})">Batalkan</button><button class="text-button" @click="$emit('openWork',finding.id)">Lihat pekerjaan<PhArrowRight :size="15" /></button></div></article></div>
 </section>
</template>
